import * as dntShim from "../../../_dnt.shims.js";
export const ESBUILD_VERSION = "0.28.1";
export const ESBUILD_WASM_URL = `https://deno.land/x/esbuild@v${ESBUILD_VERSION}/esbuild.wasm`;
export function mapEsbuildArch(arch) {
    const archMap = {
        x86_64: "x64",
        aarch64: "arm64",
    };
    return archMap[arch] ?? arch;
}
export function getEsbuildBinaryName() {
    return `@esbuild/${dntShim.Deno.build.os}-${mapEsbuildArch(dntShim.Deno.build.arch)}`;
}
export function getVFSBasePath(filePath, tempDir) {
    const denoCompileMatch = filePath.match(/^(.*\/deno-compile-[^/]+)\//);
    if (denoCompileMatch?.[1]) {
        // Deno can retain a project directory below the compile VFS root when
        // embedded dependencies have a different common ancestor.
        const moduleRoot = filePath.lastIndexOf("/src/platform/compat/");
        return moduleRoot >= denoCompileMatch[1].length
            ? filePath.slice(0, moduleRoot)
            : denoCompileMatch[1];
    }
    const parts = filePath.split("/");
    const srcIndex = parts.lastIndexOf("src");
    if (srcIndex > 0)
        return parts.slice(0, srcIndex).join("/");
    return `${tempDir}/deno-compile-veryfront`;
}
